from pathlib import Path
import json
P=Path(__file__).resolve().parent.parent;D=json.loads((P/'data.json').read_text())
pqa=next(a for a in D['areas'] if a['id']=='PQA')['publicPracticeLesson']
items=[
(["D01 signale une erreur de livrable. D02 montre un correctif livré. D03 ne relie pas le correctif au défaut constaté. Quelle suite démontre le mieux la prise en charge du problème précis ?","D01 reports a work-product defect. D02 shows a delivered fix. D03 does not connect that fix to the reported defect. What best demonstrates handling of this specific issue?"],
[["Clore sur la date de livraison du correctif, puis analyser les récidives en fin de trimestre.","Close based on the fix delivery date, then analyze recurrence at quarter end."],["Relier le défaut à l’action et vérifier le résultat sur le livrable concerné.","Link the finding to the action and check the result on the affected work product."],["Revoir d’abord toute la politique qualité sans vérifier le livrable corrigé.","Review the whole quality policy first without checking the fixed work product."],["Traiter le correctif comme une preuve de résolution de tous les défauts de cette famille.","Treat the fix as evidence that every defect in this family is resolved."]],
["Une action livrée et une action qui résout le problème ne sont pas des preuves équivalentes. Le lien et la vérification du résultat étayent la prise en charge ; ils ne prouvent pas l’absence de tout autre défaut.","A delivered action and an action that resolves the problem are not equivalent evidence. Linking and checking the result supports handling of the issue, without proving absence of every other defect."]),
(["Le plan QA D01 répartit les contrôles uniformément. D02 révèle des défauts répétés sur les interfaces. D03 montre que ces interfaces n’entrent dans aucun échantillon. Quelle révision est la mieux justifiée ?","QA plan D01 distributes checks uniformly. D02 shows repeated interface defects. D03 shows that interfaces are absent from every sample. Which revision is best justified?"],
[["Conserver la répartition uniforme pour préserver la comparabilité du nombre de contrôles.","Keep uniform allocation to preserve comparability of check counts."],["Contrôler uniquement les interfaces et supprimer toutes les autres vérifications.","Check only interfaces and remove all other evaluations."],["Réexaminer couverture et priorités du plan à partir de l’historique, puis justifier les choix.","Review plan coverage and priorities using historical findings, and justify the choices."],["Augmenter le nombre total de contrôles sans modifier les critères de sélection.","Increase total checks without changing selection criteria."]],
["L’historique révèle un angle mort du plan. Il oriente la révision de l’approche et de l’échantillonnage ; il ne prescrit pas automatiquement d’abandonner les autres contrôles.","History reveals a blind spot in the plan. It informs revision of the approach and sampling, without automatically justifying abandonment of other checks."]),
(["D01 contient le critère qualité approuvé. D02 est un échantillon sélectionné par son auteur. D03 est un autre livrable du même périmètre qui contredit le premier. Quelle évaluation est la plus objective ?","D01 contains the approved quality criterion. D02 is an author-selected sample. D03 is another work product in the same scope that contradicts it. Which evaluation is most objective?"],
[["Évaluer seulement D02 car son auteur connaît le mieux le travail réalisé.","Evaluate only D02 because its author knows the work best."],["Appliquer le même critère enregistré à D02 et D03, puis expliquer les différences de contexte.","Apply the same recorded criterion to D02 and D03, then explain contextual differences."],["Moyenner les avis des deux auteurs sans examiner les livrables.","Average the two authors’ opinions without examining the work products."],["Changer le critère pour faire correspondre les deux livrables au résultat attendu.","Change the criterion so both work products match the desired result."]],
["L’objectivité repose ici sur des critères explicites, un examen vérifiable et l’analyse de la contradiction. Ni l’autorité de l’auteur ni un vote ne remplace cette comparaison ; aucune obligation d’audit externe n’est déduite.","Objectivity here comes from explicit criteria, verifiable evaluation and analysis of the discrepancy. Neither author authority nor voting replaces that comparison; no external-audit requirement is inferred."]),
(["Un écart D01 a été communiqué. D02 porte la signature du responsable. D03 retrouve encore le défaut dans le travail courant après la clôture. Quelle suite soutient la résolution ?","Finding D01 was communicated. D02 has the owner’s signature. D03 still finds the defect in current work after closure. What supports resolution?"],
[["Conserver la clôture car le responsable a reconnu l’écart.","Keep closure because the owner acknowledged the finding."],["Envoyer une nouvelle copie du message sans modifier le suivi.","Send another copy of the message without changing follow-up."],["Reprendre le suivi, vérifier la correction effective et porter le point non résolu au niveau approprié.","Resume follow-up, verify actual correction and escalate the unresolved issue appropriately."],["Fermer le premier ticket et ouvrir un nouveau ticket sans relier les deux constats.","Close the first ticket and open another without connecting the findings."]],
["D03 contredit la clôture ; une signature démontre une reconnaissance, pas la correction. La suite porte sur communication, traitement et vérification du problème non résolu dans les dispositions applicables.","D03 contradicts closure; a signature establishes acknowledgment, not correction. Follow-up concerns communication, handling and verification of the unresolved issue under applicable arrangements."]),
(["D01 archive les contrôles QA. D02 montre des écarts répétés de même famille. D03 conserve le même plan et n’enregistre aucune décision fondée sur ces résultats. Quel usage répond le mieux à cette lacune ?","D01 archives QA evaluations. D02 shows repeated findings in the same family. D03 retains the same plan with no decision based on these results. What use best addresses this gap?"],
[["Conserver uniquement les rapports clos pour améliorer le taux de résolution apparent.","Keep only closed reports to improve the apparent resolution rate."],["Analyser les résultats conservés et tracer comment ils éclairent les décisions et le suivi qualité.","Analyze retained results and trace how they inform quality decisions and follow-up."],["Augmenter la fréquence d’archivage sans analyser les familles d’écarts.","Archive more frequently without analyzing finding families."],["Publier le total de contrôles comme preuve suffisante d’efficacité qualité.","Publish evaluation counts as sufficient proof of quality effectiveness."]],
["Conserver les résultats permet leur usage ; cela ne démontre pas encore cet usage. D02–D03 justifient de rechercher le lien entre constats, analyse et décisions, sans attribuer un effet causal non mesuré.","Retaining results enables use but does not demonstrate it. D02–D03 warrant tracing findings to analysis and decisions, without claiming an unmeasured causal effect."]),
(["L’évaluation respecte les critères enregistrés mais révèle une double saisie évitable. Aucun écart formel n’est établi. Quelle suite distingue correctement amélioration et non-conformité ?","Evaluation meets recorded criteria but reveals avoidable duplicate entry. No formal deviation is established. Which follow-up correctly distinguishes improvement from noncompliance?"],
[["Créer une non-conformité uniquement pour obtenir un budget d’amélioration.","Create a nonconformity solely to secure improvement funding."],["Consigner l’opportunité avec son contexte et la soumettre au processus de décision sur les améliorations.","Record the opportunity and its context and submit it to improvement decision-making."],["Modifier les critères après l’évaluation pour rendre la double saisie non conforme.","Change criteria after evaluation to make duplicate entry noncompliant."],["Déployer immédiatement une automatisation sans examiner coût, risque ni bénéfice.","Deploy automation immediately without assessing cost, risk or benefit."]],
["Une opportunité utile peut exister sans non-conformité. L’enregistrement conserve le constat et sa portée ; il ne force ni une qualification d’écart ni le choix immédiat d’une solution.","A useful opportunity can exist without noncompliance. Recording preserves the observation and scope, without forcing a deviation classification or immediate solution choice."])
]
for q,(prompts,options,whys) in zip(pqa['diagnostics'],items):
 for li,lang in enumerate(['fr','en']):q[lang]={'q':prompts[li],'options':[x[li] for x in options],'why':whys[li]}

# Foundation mastery focuses on each lesson's own case; remove the repeated
# document-recognition opener. Other questions still teach evidence reasoning.
F={
'F01':(['D01 ajoute des formulaires. D02 conserve quatre retards sur dix livraisons. D03 retrouve des estimations irréalistes et des dépendances non traitées. Quel choix répond au mécanisme observé ?','D01 adds forms. D02 still records four delays in ten releases. D03 finds unrealistic estimates and unhandled dependencies. Which choice addresses the observed mechanism?'],[['Revoir estimations et dépendances, puis mesurer l’effet sur des livraisons comparables.','Review estimates and dependencies, then measure the effect on comparable releases.'],['Augmenter le nombre de formulaires pour rendre l’effort d’amélioration plus visible.','Increase form counts to make improvement effort more visible.'],['Attribuer la baisse de coût documentaire à une réduction des retards.','Attribute lower documentation costs to reduced delays.'],['Choisir le projet le plus performant comme preuve du succès de tous.','Use the best project as proof that every project improved.']]),
'F02':(['D01 contient 31 lignes de sigles PA. D02 ne relie ces lignes à aucune pratique réalisée. D03 ne définit pas le périmètre. Que manque-t-il avant d’utiliser ce tableau comme préparation ?','D01 has 31 PA acronym rows. D02 links them to no performed practices. D03 defines no scope. What is missing before this table can support preparation?'],[['Relier la vue et le périmètre aux sujets applicables et aux traces d’exécution pertinentes.','Connect the view and scope to applicable topics and relevant implementation evidence.'],['Compter chaque ligne comme une pratique individuelle démontrée.','Count each row as a demonstrated individual practice.'],['Déduire la maturité du pourcentage de sigles renseignés.','Infer maturity from the percentage of acronyms filled in.'],['Additionner des domaines comme s’ils étaient les niveaux d’un même processus.','Add domains as if they were levels of one process.']]),
'F03':(['D01 est une procédure commune. D02 montre deux équipes qui l’appliquent. D03 montre une troisième équipe sans trace et aucune adaptation expliquée. Quelle conclusion est défendable ?','D01 is a common procedure. D02 shows two teams using it. D03 shows a third without records and no explained tailoring. Which conclusion is defensible?'],[['Un usage partiel est étayé ; l’application sur le périmètre et les adaptations restent à vérifier.','Partial use is supported; scope-wide implementation and tailoring still need examination.'],['La diffusion du document suffit à démontrer un niveau organisationnel avancé.','Document distribution establishes an advanced organizational level.'],['L’absence de trace dans une équipe invalide les observations des deux autres.','One team’s missing records invalidate observations from the other two.'],['Chaque équipe qui applique la procédure reçoit automatiquement un niveau de maturité.','Every team applying the procedure automatically receives a maturity rating.']]),
'F04':(['D01 est le score individuel de 98 % du responsable. D02–D03 montrent des lacunes de gestion des changements et de revues dans l’entreprise. Quel usage du score est justifié ?','D01 is the manager’s individual 98% score. D02–D03 show gaps in company change management and reviews. Which use of the score is justified?'],[['Le score renseigne l’entraînement individuel ; examiner séparément les pratiques dans le périmètre organisationnel.','The score informs individual learning; examine organizational practices in their own scope.'],['Convertir le score en niveau de maturité puisque le responsable représente l’entreprise.','Convert the score to maturity because the manager represents the company.'],['Considérer les lacunes résolues car leur responsable connaît la bonne réponse.','Treat gaps as resolved because their owner knows the right answer.'],['Remplacer les entretiens des équipes par une copie du résultat individuel.','Replace team interviews with the individual result.']]),
'F05':(['D01 est une politique signée il y a trois ans. D02 ne contient aucune revue dans quatre projets. D03 rapporte que les équipes ne connaissent pas la procédure. Quel constat respecte les preuves ?','D01 is a policy signed three years ago. D02 contains no reviews across four projects. D03 says teams do not know the procedure. Which finding respects the evidence?'],[['La politique existe ; l’application n’est pas démontrée dans l’échantillon et demande une enquête ciblée.','The policy exists; implementation is unsupported in the sample and needs focused investigation.'],['La signature établit la réalisation des revues même sans traces.','The signature establishes that reviews happened even without records.'],['L’absence dans l’échantillon prouve l’absence absolue dans tous les projets passés.','Absence in the sample proves absolute absence in every past project.'],['La politique doit être supprimée avant toute vérification supplémentaire.','The policy must be deleted before further investigation.']]),
'F06':(['D01 décrit trois agences dans le périmètre. D02 montre le pilote de l’agence centrale. D03 révèle des plans obsolètes dans les deux autres. Quel échantillonnage répond à l’incertitude ?','D01 defines three in-scope agencies. D02 shows the central pilot. D03 reveals obsolete plans in the other two. Which sampling addresses the uncertainty?'],[['Examiner des travaux des autres agences et expliquer leurs différences pertinentes avec le pilote.','Examine work from the other agencies and explain relevant differences from the pilot.'],['Ajouter seulement d’autres exemples du pilote pour augmenter la taille de l’échantillon.','Add only more pilot examples to increase sample size.'],['Retirer les agences moins performantes après avoir vu leurs résultats.','Remove poorer-performing agencies after seeing their results.'],['Pondérer les avis par ancienneté plutôt que comparer les travaux.','Weight opinions by seniority instead of comparing work.']]),
'F07':(['D01 contient dix corrections similaires de configuration. D02 clôt chaque ticket. D03 montre la réapparition du même défaut. Quelle suite traite la faiblesse récurrente ?','D01 contains ten similar configuration fixes. D02 closes every ticket. D03 shows the same defect recurring. Which follow-up addresses the recurring weakness?'],[['Examiner le mécanisme de déploiement, agir sur la cause corroborée et vérifier la récidive.','Examine the deployment mechanism, address the corroborated cause and check recurrence.'],['Réduire le délai de clôture sans modifier le mécanisme.','Reduce closure time without changing the mechanism.'],['Fusionner les tickets pour faire disparaître la répétition du tableau de bord.','Merge tickets so repetition disappears from the dashboard.'],['Déduire l’efficacité préventive du nombre de corrections livrées.','Infer preventive effectiveness from the number of delivered fixes.']]),
'F08':(['D01 annonce une baisse de 40 % du délai. D02 exclut les incidents complexes après intervention. D03 conserve le titre de la métrique. Que vérifier avant d’attribuer une amélioration ?','D01 claims a 40% delay reduction. D02 excludes complex incidents after intervention. D03 keeps the metric title unchanged. What must be checked before attributing improvement?'],[['Rétablir des populations et définitions comparables et séparer changement de mesure et effet opérationnel.','Restore comparable populations and definitions and separate measurement changes from operational effect.'],['Accepter la baisse car le titre de l’indicateur n’a pas changé.','Accept the fall because the indicator title is unchanged.'],['Multiplier les moyennes pour compenser les incidents retirés sans leurs données.','Multiply the averages to compensate for excluded incidents without their data.'],['Déclarer toute mesure statistique inutile parce qu’un biais a été trouvé.','Declare all statistical measurement useless because one bias was found.']]),
'F09':(['D01 consacre toutes les révisions au développement. D02 ne contient que des sessions de 20 questions sans chronomètre. D03 rappelle la forte place de Core/Virtual dans le guide public. Quelle adaptation est fondée ?','D01 focuses all study on development. D02 has only untimed 20-question sessions. D03 shows Core/Virtual has substantial weight in the public guide. Which adaptation is supported?'],[['Rééquilibrer les domaines et pratiquer des sessions longues, en revérifiant les règles officielles applicables à la date d’examen.','Rebalance domains and practice longer sessions while rechecking official rules for the exam date.'],['Déduire un score officiel à partir de la moyenne des petits quiz.','Infer an official score from short-quiz averages.'],['Supprimer les autres domaines pour renforcer le meilleur domaine.','Drop other domains to strengthen the best one.'],['Traiter un seuil interne de 80 % comme le seuil officiel de réussite.','Treat an internal 80% target as the official passing score.']])}
for l in D['foundations']:
 prompts,opts=F[l['id']]
 for li,lang in enumerate(['fr','en']):
  q=l['masteryQuestions'][lang][0];answer=q['answer'];options=[x[li] for x in opts];options.insert(answer,options.pop(0));q['q']=l['id']+' · '+prompts[li];q['options']=options
  q['why']=('The conclusion must follow the actual records and preserve scope and uncertainty. '+opts[0][1] if li else 'La conclusion doit découler des pièces et préserver périmètre et incertitude. '+opts[0][0])
  l['caseLab'][lang]['context']=(l['en'] if li else l['deep'])['story']
(P/'data.json').write_text(json.dumps(D,ensure_ascii=False,separators=(',',':')))
print('Six PQA checkpoints and nine foundation evidence questions refined in both languages.')
